// Dane z webhooka są w $json.body - spłaszczamy je, żeby dalej używać $json.pole
const src = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const required = ["question"];
const missing = required.filter((k) => src[k] === undefined || src[k] === null || String(src[k]).trim() === '');
if (missing.length) {
  throw new Error('Brak wymaganych pól: ' + missing.join(', '));
}
const clean = {};
for (const [k, v] of Object.entries(src)) {
  clean[k] = typeof v === 'string' ? v.trim().slice(0, 5000) : v;
}
if (clean.email !== undefined && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(clean.email))) {
  throw new Error('Niepoprawny adres e-mail');
}
return { json: { ...clean, _odebrano: new Date().toISOString() } };

const rows = $input.all().map((i) => i.json).filter((r) => r && r.content);
const kontekst = rows.map((r, n) => '[' + (n + 1) + '] ' + r.content).join('\n\n').slice(0, 10000);
const zrodla = rows.map((r) => r.metadata?.source || r.metadata?.title || null).filter(Boolean);
return [{ json: { question: $('Walidacja danych').first().json.question, kontekst, zrodla } }];

const SYSTEM = "Odpowiadasz na pytanie WYŁĄCZNIE na podstawie ponumerowanych fragmentów dokumentacji. Jeśli fragmenty nie zawierają odpowiedzi – powiedz to wprost. Po polsku, zwięźle.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"odpowiedz\": tekst, \"wykorzystaneFragmenty\": tablica numerów fragmentów}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Fragmenty:\n${$json.kontekst || "(brak)"}\n\nPytanie: ${$json.question}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (odpowiedź RAG)').item.json };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"odpowiedz":"","wykorzystaneFragmenty":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };
